import Foundation
import AirlineEmpireCore

/// The world the network is drawn on (docs/MAP_ARCHITECTURE.md §3).
///
/// ## Where this geography comes from
///
/// **Natural Earth 1:50m land, public domain.** Downloaded, simplified with
/// Douglas–Peucker at 0.15°, rounded to two decimal places (~1.1 km, well
/// under a pixel at world zoom), and embedded below.
///
/// It replaces a hand trace, and that trace's own comment explained why it
/// existed: *"the environment has no network access to fetch Natural Earth,
/// and a coarse hand trace that ships beats an accurate one that does not."*
/// That was the right call under that constraint. The constraint expired; the
/// decision was re-made rather than inherited.
///
/// | | before | after |
/// | --- | --- | --- |
/// | polygons | 16 | **314** |
/// | points | 631 | **6,950** |
///
/// The reason to care is not prettiness. The eighty airports are at real
/// coordinates — Arlanda, Heathrow, Charles de Gaulle, JFK, Haneda — and were
/// being plotted onto a coastline where Europe was a few dozen points. Precise
/// data on imprecise geography puts airports in the sea.
///
/// ## What is deliberately left out
///
/// - **Antarctica.** The hand trace omitted it and so does this: no airline in
///   the game flies there, it is a 2,805-point polygon spanning the entire
///   longitude range, and the projection already clips at ±80°.
/// - **Islands below ~0.6° across**, which are sub-pixel at world zoom and
///   would be a thousand polygons of noise.
/// - **Rivers.** They compete with the route lines that are the map's subject.
///
/// One landmass legitimately spans 197° of longitude — Afro-Eurasia, West
/// Africa to the Bering Strait — exactly as the hand-traced `africaEurasia`
/// did. That is real geography, not an antimeridian wrap, and the renderer's
/// existing `visibleWorldOffsets` handling covers it.
///
/// ## Why a string and not an array literal
///
/// 6,950 coordinate pairs written as Swift tuples would be a type-checking
/// problem measured in minutes. A string literal costs the compiler nothing
/// and is parsed once, lazily, on first access.
///
/// Presentation only. Nothing here reaches the simulation; airport positions
/// come from `airports.json` through `MapModel`, never from this file.
///
/// *Made with Natural Earth.*
enum WorldGeometry {

    /// Coastlines in map space, largest first so the renderer can fill them
    /// back to front without sorting.
    static let landmasses: [[MapPoint]] = outlines
        .sorted { $0.count > $1.count }
        .map { outline in
            outline.map { MapPoint(coordinate: Coordinate(latitude: $0.0,
                                                          longitude: $0.1)) }
        }

    /// Meridians and parallels, as pre-projected line segments.
    ///
    /// A graticule is what makes a dark field read as a *map* rather than a
    /// background, and it gives the eye something to measure a route against.
    /// Every 30° — dense enough to structure the plane, sparse enough to stay
    /// out of the way.
    static let graticule: [[MapPoint]] = {
        var lines: [[MapPoint]] = []
        for longitude in stride(from: -180.0, through: 180.0, by: 30) {
            lines.append(stride(from: -80.0, through: 80.0, by: 10).map {
                MapPoint(coordinate: Coordinate(latitude: $0, longitude: longitude))
            })
        }
        for latitude in stride(from: -60.0, through: 80.0, by: 30) {
            lines.append(stride(from: -180.0, through: 180.0, by: 10).map {
                MapPoint(coordinate: Coordinate(latitude: latitude, longitude: $0))
            })
        }
        return lines
    }()

    /// The equator, drawn a shade stronger than the rest of the grid.
    static let equator: [MapPoint] = stride(from: -180.0, through: 180.0, by: 10)
        .map { MapPoint(coordinate: Coordinate(latitude: 0, longitude: $0)) }

    // MARK: - Coastlines, (latitude, longitude)

    /// Coastlines, parsed from the embedded data on first use.
    private static let outlines: [[(Double, Double)]] = parse(landData)

    /// Inland water, drawn over the land it sits in. The Caspian, the Great
    /// Lakes, Baikal and Victoria are orientation landmarks — a lake-shaped
    /// hole in a continent is far more noticeable than a missing fjord.
    static let lakes: [[MapPoint]] = parse(lakeData).map { outline in
        outline.map { MapPoint(coordinate: Coordinate(latitude: $0.0,
                                                      longitude: $0.1)) }
    }

    /// One polygon per line; `lat,lon` pairs separated by spaces.
    private static func parse(_ data: String) -> [[(Double, Double)]] {
        data.split(separator: "\n").map { line in
            line.split(separator: " ").compactMap { pair in
                let parts = pair.split(separator: ",")
                guard parts.count == 2,
                      let lat = Double(parts[0]),
                      let lon = Double(parts[1]) else { return nil }
                return (lat, lon)
            }
        }
    }

